smart.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 17px;
  line-height: 1.72;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  line-height: 1.3;
}

.smc-root h2 {
  border-top: 1px solid var(--smc-border);
  font-size: 26px;
  margin-top: 38px;
  padding-top: 28px;
}

.smc-root h3 {
  font-size: 20px;
  margin-top: 20px;
}

.smc-root p {
  margin-top: 14px;
}

.smc-section ul {
  margin: 14px 0 0;
  padding-left: 20px;
  display: grid;
  gap: 10px;
}

.smc-section li {
  line-height: 1.68;
}

.smc-root em {
  font-style: italic;
}

.smc-root strong {
  font-weight: 700;
  color: var(--smc-primary);
}

.smc-root a {
  color: var(--smc-accent);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary);
}

.smc-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  padding: 24px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  margin-bottom: 24px;
}

.smc-eyebrow {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--smc-accent);
  margin: 0 0 8px;
}

.smc-intro-copy h2 {
  border-top: 0;
  font-size: 28px;
  margin-top: 0;
  padding-top: 0;
  line-height: 1.25;
}

.smc-intro-media {
  margin: 0;
  text-align: center;
}

.smc-intro-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  object-fit: cover;
  border: 1px solid var(--smc-border);
}

.smc-intro-media figcaption,
.smc-lifestyle figcaption,
.smc-detail-media figcaption {
  color: var(--smc-muted);
  font-size: 13.5px;
  line-height: 1.5;
  margin-top: 10px;
  font-style: italic;
  text-align: center;
}

.smc-entity-box {
  background: color-mix(in srgb, var(--smc-primary) 5%, var(--smc-bg));
  border: 1.5px solid color-mix(in srgb, var(--smc-primary) 22%, var(--smc-border));
  border-radius: var(--smc-radius);
  padding: 22px 20px;
  margin: 24px 0 32px;
}

.smc-entity-title {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--smc-primary);
  margin: 0 0 14px;
}

.smc-entity-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
}

.smc-entity-item {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 12px 14px;
}

.smc-entity-label {
  display: block;
  font-size: 12.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--smc-muted);
  margin-bottom: 4px;
}

.smc-entity-val {
  display: block;
  font-size: 15px;
  font-weight: 600;
  color: var(--smc-text);
  line-height: 1.45;
}

.smc-feature-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  margin-top: 22px;
}

.smc-feature-card {
  position: relative;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 22px 20px 20px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

.smc-card-badge {
  display: inline-block;
  font-size: 13px;
  font-weight: 800;
  color: var(--smc-accent);
  background: color-mix(in srgb, var(--smc-accent) 12%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-accent) 25%, var(--smc-border));
  padding: 3px 10px;
  border-radius: 999px;
  margin-bottom: 8px;
}

.smc-feature-card h3 {
  margin: 6px 0 10px;
  font-size: 18.5px;
}

.smc-feature-card p {
  color: var(--smc-muted);
  font-size: 15.5px;
  margin: 0;
  line-height: 1.65;
}

.smc-table-wrap {
  overflow-x: auto;
  margin-top: 20px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-bg);
}

.smc-compare-table {
  border-collapse: collapse;
  width: 100%;
  font-size: 15px;
}

.smc-compare-table th,
.smc-compare-table td {
  border-bottom: 1px solid var(--smc-border);
  padding: 13px 14px;
  text-align: left;
  vertical-align: top;
}

.smc-compare-table th {
  background: color-mix(in srgb, var(--smc-primary) 8%, var(--smc-bg));
  color: var(--smc-primary);
  font-weight: 700;
  font-family: var(--smc-font-heading);
}

.smc-compare-table tr:last-child td {
  border-bottom: 0;
}

.smc-lifestyle {
  margin: 26px 0;
  text-align: center;
}

.smc-lifestyle img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
}

.smc-detail-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 22px;
  margin-top: 20px;
  align-items: center;
}

.smc-detail-copy ul {
  list-style: none;
  padding: 0;
  margin: 16px 0 0;
  display: grid;
  gap: 12px;
}

.smc-detail-copy li {
  padding-left: 24px;
  position: relative;
  font-size: 15.5px;
  line-height: 1.6;
}

.smc-detail-copy li::before {
  content: "✔";
  position: absolute;
  left: 0;
  color: var(--smc-accent);
  font-weight: 800;
}

.smc-detail-media {
  margin: 0;
  text-align: center;
}

.smc-detail-media img {
  display: block;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  height: auto;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
}

.smc-note-box {
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-left: 4px solid var(--smc-primary);
  border-radius: var(--smc-radius);
  padding: 20px 22px;
  margin-top: 28px;
}

.smc-note-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--smc-primary);
  margin: 0 0 8px;
}

.smc-note-box p:last-child {
  margin: 0;
  font-size: 15.5px;
  line-height: 1.68;
}

.smc-verdict-card {
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 26px 22px;
  margin-top: 20px;
}

.smc-verdict-lead {
  font-size: 16.5px;
  line-height: 1.7;
  margin: 0 0 20px;
}

.smc-verdict-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  margin: 20px 0;
}

.smc-verdict-item {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-left: 4px solid var(--smc-accent);
  border-radius: var(--smc-radius);
  padding: 16px 18px;
}

.smc-verdict-item h3 {
  margin: 0 0 6px;
  font-size: 17px;
}

.smc-verdict-item p {
  margin: 0;
  font-size: 15px;
  color: var(--smc-muted);
  line-height: 1.6;
}

.smc-verdict-conclusion {
  background: color-mix(in srgb, var(--smc-accent) 8%, var(--smc-bg));
  border: 1px dashed color-mix(in srgb, var(--smc-accent) 25%, var(--smc-border));
  border-radius: var(--smc-radius);
  padding: 16px 18px;
  margin: 20px 0 0;
  font-size: 16px;
  line-height: 1.65;
}

.smc-faq {
  margin-top: 38px;
}

.smc-faq-list details {
  border-top: 1px solid var(--smc-border);
  padding: 16px 0;
}

.smc-faq-list details:last-child {
  border-bottom: 1px solid var(--smc-border);
}

.smc-faq-list summary {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  font-size: 17.5px;
  cursor: pointer;
  line-height: 1.4;
}

.smc-faq-list details p {
  color: var(--smc-muted);
  margin: 10px 0 0;
  font-size: 15.5px;
  line-height: 1.65;
}

.smc-related {
  margin-top: 40px;
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}

.smc-related strong {
  display: block;
  margin-bottom: 12px;
  font-size: 15px;
}

.smc-related-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.smc-related-links a {
  display: inline-block;
  padding: 7px 15px;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: 999px;
  text-decoration: none;
  font-size: 14px;
  color: var(--smc-text);
  font-weight: 600;
  transition: all .2s ease;
}

.smc-related-links a:hover {
  border-color: var(--smc-accent);
  color: var(--smc-accent);
}

@container smc (min-width: 720px) {
  .smc-intro {
    grid-template-columns: 1.15fr .85fr;
    padding: 32px;
    align-items: center;
  }
  .smc-entity-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .smc-feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smc-detail-grid {
    grid-template-columns: 1.1fr .9fr;
  }
  .smc-verdict-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@container smc (max-width: 440px) {
  .smc-root {
    font-size: 15.5px;
  }
  .smc-intro {
    padding: 18px 14px;
  }
  .smc-verdict-card {
    padding: 18px 14px;
  }
}

